      // R-05 本卡规则。纯函数不读写聊天、MVU 或页面；测试直接加载本段。
      var RATING_RULE_VERSION = "r05-v1";
      var RATING_AXES = ["attack", "defense", "magic", "control", "physical", "luck"];
      var RATING_CORE = RATING_AXES.slice(0, 4);
      var RATING_GRADES = ["A", "B+", "B", "C+", "C", "D+", "D", "E+", "E", "F+", "F"];
      var RATING_ANCHORS = {
