          ctx.save(); ctx.beginPath(); ctx.arc(855, 155, 80, 0, Math.PI * 2); ctx.clip();
          ctx.fillStyle = "#d7c6a8"; ctx.fillRect(775, 75, 160, 160);
          if (portrait) {
