// GENERATED by scripts/build-plot-injector.mjs. Edit runtime, bootstrap or story sources.
(function () {
'use strict';
// GBK 原文目录是唯一顺序来源；浏览器产物在构建时内联这些数据和函数。
const STORY_VOLUMES = [{"volume":1,"title":"第1卷","chapters":[{"key":"序章","title":"序章 早晨的相遇","aliases":[],"summary":"原作候选：一辉返回自己居住的第一学生宿舍405室，意外撞见陌生少女，引发双方惊慌与误会。章节以少女的尖叫打破清晨宁静收束，后续应围绕当事人的反应展开。"},{"key":"第一章","title":"第一章 天才骑士与落第骑士","aliases":[],"summary":"原作候选：一辉在理事长室说明宿舍误会，与史黛菈的冲突随后进入剑与魔力的较量。他以自身的训练回应能力等级差距，两人的相处也从对立逐渐转向同行。"},{"key":"第二章","title":"第二章 来自旧巢的访客","aliases":[],"summary":"原作候选：史黛菈坚持跟上一辉的训练节奏，一辉也在教室中应对同学的挑衅。久别的妹妹珠雫现身，令兄妹重逢与同伴之间的相处出现新的摩擦。"},{"key":"第三章","title":"第三章 解放军（Rebellion）","aliases":[],"summary":"原作候选：珠雫对兄长过去的处境重新思考，一行人随后面对购物中心的人质事件，商议接近被困者的方法。事件之后，校内选拔临近，一辉确认首战将对上桐原。"},{"key":"第四章","title":"第四章 初战","aliases":[],"summary":"原作候选：校内选拔赛展开，珠雫先以水之防御应对雷击，一辉则迎战具有隐匿能力的桐原。观察、心理压力与突破时机成为交锋关键，原作中的一辉最终获得首战胜利。"},{"key":"终章","title":"终章 月下誓言","aliases":[],"summary":"原作候选：首战后，一辉在恢复伤势时面对自己对史黛菈的心意。两人在月下约定继续迎战未知对手，争取于七星剑王决胜战再次相遇。"}]},{"volume":2,"title":"第2卷","chapters":[{"key":"序章","title":"序章 遥远的记忆","aliases":[],"summary":"原作候选：少女回想父亲在身体衰弱前，希望把剑术奥义托付给自己的往事。温暖的传授与如今失去重要事物的处境相对照，为后续取回尊严的冲突奠定背景。"},{"key":"第一章","title":"第一章 拜入师门","aliases":[],"summary":"原作候选：一辉继续参加选拔并教授武术，与三年级的绫辻绚濑相识后，开始具体指导她的剑术。师徒之间因训练产生信任，也改变了史黛菈等人观察一辉的日常视角。"},{"key":"第二章","title":"第二章 逢魔时刻","aliases":[],"summary":"原作候选：外出聚餐牵出绚濑与藏人的关系，而新公布的选拔安排让一辉与绚濑成为对手。绚濑为削弱一辉而制造坠落险情，迫使他提前使用一刀修罗，师徒信任因此受到打击。"},{"key":"第三章","title":"第三章 绫辻绚濑","aliases":[],"summary":"原作候选：绚濑面对背叛恩人的悔意，也回想父亲败给藏人后自己失去方向的过程。她与一辉的选拔战成为正视自身执念的契机，原作以她承认需要帮助并重新抓住剑士尊严推进。"},{"key":"第四章","title":"第四章 决战！〈落第骑士（Worst one）〉VS〈剑士杀手（Sword Eater）〉","aliases":[],"summary":"原作候选：一辉为与藏人的正式交锋备战，战斗中面对难以靠惯常读招破解的神速反射。绫辻剑术的传承成为突破的重要线索，绚濑也重新立下依靠自身力量成长的目标。"},{"key":"终章","title":"终章 寒冰微笑","aliases":[],"summary":"原作候选：击败强敌后，一辉在校内的评价改变，众人开始议论他与学生会长雷切谁更强。日常交流继续推进，珠雫则在临近的新战斗前显露强烈斗志。"}]},{"volume":3,"title":"第3卷","chapters":[{"key":"序章","title":"序章 珠雫的挑战","aliases":[],"summary":"原作候选：珠雫在比赛前回想幼时受到优待、却未能察觉兄长遭遇的经历。她决意在眼前的战斗挑战自身极限，比赛开始成为回忆转入行动的节点。"},{"key":"第一章","title":"第一章〈深海魔女（Lorelei）〉VS〈雷切〉","aliases":[],"summary":"原作候选：珠雫与刀华在紧张的观战气氛中展开较量，原作由刀华赢下这场高水平对决。此后的交流让一辉与史黛菈答应协助学生会，为前往奥多摩的集训设施作准备。"},{"key":"第二章","title":"第二章 奥多摩的怪物","aliases":[],"summary":"原作候选：一辉与史黛菈随学生会前往奥多摩集训场，途中遇上具有敌意的岩石巨人等突发状况。章末黑铁家的恶意转为伦理委员会的正式召集，一辉的骑士资格受到威胁。"},{"key":"第三章","title":"第三章 身陷逆境的〈落第骑士（Worst one）〉","aliases":[],"summary":"原作候选：伦理委员会的调查让一辉承受明显不平等的对待，围绕骑士前途的压力持续累积。即使身体已经衰弱，他仍须面对以交叉距离见长的刀华，思考自己背负的期待。"},{"key":"第四章","title":"第四章 一刀两断","aliases":[],"summary":"原作候选：一辉在病弱与多方期待中赶赴刀华的决战，双方均认真准备以一刀决出高下。一辉在极限交锋中进一步压缩力量，原作于此呈现一刀罗刹与刀华倾尽全力的回应。"},{"key":"终章","title":"终章 无冕剑王（Another one）","aliases":[],"summary":"原作候选：校内选拔结束后，六名代表接受正式任命，刀华把寄托落选者愿望的校旗交给一辉。舞台转向全国大赛，同时晓的势力以夺取七星剑武祭主导权为目标开始行动。"}]},{"volume":4,"title":"第4卷","chapters":[{"key":"序章","title":"序章 雪国的街道","aliases":[],"summary":"原作候选：雪国教会旁，一群贫困孩子靠相互照顾维持生活，年长者教导他们珍惜伙伴。艾莉丝从手织围巾中感受到温暖，盼望来日仍能与同伴平安度过。"},{"key":"第一章","title":"第一章 强化集训","aliases":[],"summary":"原作候选：七星剑武祭临近，选手们进入强化集训期间，训练之外仍有一辉与史黛菈的日常相处。与天音的接触却在一辉心中留下难以解释的不安，平静中逐渐出现凶兆。"},{"key":"第二章","title":"第二章 阴谋蠢动","aliases":[],"summary":"原作候选：艾莉丝与尤利的旧日经历，同他现在和珠雫的交流交织展开。有栖院必须面对卧底任务与既有关系之间的矛盾，并预想真相揭开后同伴的目光。"},{"key":"第三章","title":"第三章 晓，进军","aliases":[],"summary":"原作候选：晓学园袭击破军，通信失败与针对同伴的威胁让事态迅速扩大。珠雫和一辉重新会合后决定赶往有栖院被带走的方向，救援取代原本的平静安排。"},{"key":"第四章","title":"第四章 过早的决战","aliases":[],"summary":"原作候选：破军一方在晓的攻势下苦战，一辉更与世界级剑士爱德怀斯交锋。教师介入后，晓因继续冲突的风险而撤退，袭击造成的伤势与背后赞助者的问题仍然留下。"},{"key":"终章","title":"终章 幕后黑手（fixer）","aliases":[],"summary":"原作候选：晓学园背后的政治目的公开，破军需要重新安排受袭后的参赛阵容。史黛菈选择接受西京的严苛特训，而公布的赛程把一辉首战的对手指向现任七星剑王诸星雄大。"}]},{"volume":5,"title":"第5卷","chapters":[{"key":"序章","title":"序章 祭典的乐声","aliases":[],"summary":"原作候选：月影设立国立伐刀者教育机构的举动，被视为对既有联盟秩序的挑战。社会对独立、袭击与政治利用赛事的看法分裂，七星剑武祭在争论中逼近。"},{"key":"第一章","title":"第一章 全国的劲敌们","aliases":[],"summary":"原作候选：大赛开幕前，国内外观众与各校选手陆续聚集，破军受袭令赛事关注度更高。一辉等人与晓的选手相遇，黑乃则强调真正投入比赛的热情仍是竞争的重要力量。"},{"key":"第二章","title":"第二章 浪速之星","aliases":[],"summary":"原作候选：诸星带一辉等人接触大阪日常，其曾遭重大事故、历经复健重返赛场的经历逐渐被讲明。对这位对手的理解加深后，三十二名选手迎来七星剑武祭开幕。"},{"key":"第三章","title":"第三章 七星剑武祭·开幕","aliases":[],"summary":"原作候选：刀华在病房醒来，赛事转播将她与留守者重新连到比赛现场。一辉与诸星的开幕交锋进入枪术与剑术的攻防，诸星抓住所见破绽继续施压。"},{"key":"第四章","title":"第四章 决战·〈无冕剑王〉VS〈七星剑王〉","aliases":[],"summary":"原作候选：一辉与诸星继续争夺首轮胜利，诸星的顽强及其妹妹小梅的心情也成为战斗之外的视点。原作以一辉取胜、诸星受到观众肯定收束，并迎来史黛菈及时赶到会场。"},{"key":"终章","title":"终章 好戏登场","aliases":[],"summary":"原作候选：史黛菈赶上大赛后，主动提出由自己迎战所有剩余B区选手的四对一特别规则。她希望亲自回应晓对同伴造成的伤害，一辉则选择相信她经过特训取得的力量。"}]},{"volume":6,"title":"第6卷","chapters":[{"key":"间章1","title":"间章 反射术士","aliases":["间章"],"summary":"原作候选：史黛菈将独自参加B区四对一比赛，留守观战的刀华与彼方讨论潜在风险。彼方曾与多多良交手的经验显示，对方反射攻击的能力可能成为高火力史黛菈的棘手障碍。"},{"key":"第五章","title":"第五章 快刀斩乱麻","aliases":[],"summary":"原作候选：史黛菈迎战B区四名对手，激烈交锋的余波甚至波及观众区域。原作以她击败对手并改变B区后续赛程收束，使她提前取得准决赛资格。"},{"key":"第六章","title":"第六章 初战终了","aliases":[],"summary":"原作候选：首轮结束后，选手们评估史黛菈展现的新力量，也在相处与交谈中认识接下来的对手。王马对一辉提出忠告，随后大会宣布缩短赛程，将第二轮和第三轮集中在同一天。"},{"key":"第七章","title":"第七章 七星剑武祭第二轮战·开战","aliases":[],"summary":"原作候选：赛程临时缩短使第二轮在困惑中展开，选手们不得不面对连续作战的压力。藏人与莎拉的比赛展示了色彩及绘画实体化能力，一辉由此认识到下一轮对手的危险。"},{"key":"间章2","title":"间章 转暗","aliases":[],"summary":"原作候选：白夜准备与一辉交手，期待以周密推演完成二十三手的理性攻防。比赛开始后，一辉的一刀罗刹却在开局便打断他的意识，计划与现实骤然分离。"}]},{"volume":7,"title":"第7卷","chapters":[{"key":"间章1","title":"间章 毫无余韵的胜利","aliases":["间章"],"summary":"原作候选：一辉以一刀罗刹迅速结束与白夜的比赛，观众看到的是压倒性的短暂胜利。离开战圈后，他却显露身体负担，并要立即面对同日第三轮与莎拉交战的压力。"},{"key":"第八章","title":"第八章 喧闹不休的医务室","aliases":[],"summary":"原作候选：医务室中的一行人关注珠雫的比赛，讨论她对付特殊步法时的困难。史黛菈与莎拉的相处又引出一连串尴尬和争执，一辉在混乱中处理即将交战者之间的日常关系。"},{"key":"第九章","title":"第九章 战士们略微喧嚣的中场休息","aliases":[],"summary":"原作候选：比赛间歇，一行人外出处理衣物与走失婴儿等日常状况，一辉进一步了解莎拉为何执着于父亲未完成的画。她的经历也触动一辉对亲情的思考，众人随后返回会场准备第三轮。"},{"key":"第十章","title":"第十章 七星剑舞祭第三轮战·开战","aliases":[],"summary":"原作候选：第三轮争夺各区席位，一辉迎战能够以绘画构筑兵力与强者形象的莎拉。假爱德怀斯迫使他在致命速度差中寻找突破，原作以一辉获胜、通往决赛的距离缩短收束。"},{"key":"间章2","title":"间章 鲜血的结局","aliases":[],"summary":"原作候选：一辉带伤关注珠雫与天音争夺D区席位的比赛，而天音此前的不战而胜使其能力仍难判断。转播中的流血结局突然打破期待，为一辉接下来的准决赛蒙上阴影。"}]},{"volume":8,"title":"第8卷","chapters":[{"key":"间章1","title":"间章 为了让自己不再后悔","aliases":["间章"],"summary":"原作候选：珠雫回想自己幼时沉浸于兄长宠爱，却忽略他独自承受的家族阴影。她如今决意主动帮助一辉，甚至愿意为此承担失去一切的代价。"},{"key":"第十一章","title":"第十一章 鲜血的真相","aliases":[],"summary":"原作候选：珠雫试图绕开天音的因果能力，以有栖院协助的奇袭先行伤及对手。行动失败后，监控证据支持了天音的解释，一辉也被迫面对月影预先掌握条件的谈判。"},{"key":"第十二章","title":"第十二章 双龙相克","aliases":[],"summary":"原作候选：准决赛由史黛菈与王马争夺决赛席位，史黛菈同时回想西京训练中对自身缺陷的追问。她在交锋中展现成长，原作以击败王马、率先进军决胜赛收束。"},{"key":"第十三章","title":"第十三章 阴云密布的准决赛","aliases":[],"summary":"原作候选：一辉在准决赛面对天音操纵因果的力量，表面上的胜负不断被生死变化扰动。原作虽由裁判宣告一辉获胜，赛后却暴露出他的生命状态仍处于严重危机之中。"},{"key":"间章2","title":"间章 姗姗来迟","aliases":[],"summary":"原作候选：一辉在赛后失去生命迹象，医疗团队紧急抢救，身体不同部位相继出现的异常让亲友焦急等待。他醒来后再次面对史黛菈，赛事方面确认双方战意并重新安排决赛时间。"}]},{"volume":9,"title":"第9卷","chapters":[{"key":"第十四章","title":"第十四章 战魂高昂","aliases":[],"summary":"原作候选：延后的决赛临近，众人期待一辉与史黛菈真正交锋，一辉也在与刀华的切磋中继续审视技艺。史黛菈调整饮食与状态，双方把剩余时间用于迎接最重要的对手。"},{"key":"终章（前）","title":"终章（前） 约定之刻","aliases":[],"summary":"原作候选：七星剑武祭冠军赛展开，一辉与史黛菈以各自的力量和技艺全力相争。原作以两人耗尽体力离场收束，场外强者也注意到一辉在极限中出现了超出既有因果束缚的变化。"},{"key":"终章（后）","title":"终章（后） 并立之人","aliases":[],"summary":"原作候选：大战后的休养让一辉重新面对史黛菈及身边的人，两人确认了继续同行的心意。颁奖典礼把一辉长期追求的七星剑王称号化为正式认可，故事以两人并立于领奖舞台的画面收束。"}]},{"volume":10,"title":"第10卷","chapters":[{"key":"序章","title":"来自地狱的蜘蛛","aliases":[],"summary":"东南亚遗迹中，操纵大量机关人偶的神秘人物反复观看史黛菈击毁摄影机的影像。他从她的高洁与反抗中产生恶意，决定亲自毁掉她珍视的一切。"},{"key":"第一章","title":"庆典结束之后","aliases":[],"summary":"七星剑武祭落幕，一辉与破军同伴留在大阪参加诸星家的庆功宴。黑骑士突袭及月影展示的东京火海预知，使短暂休憩蒙上未来危机；众人随后各自踏向新的目标。"},{"key":"第二章","title":"〈深海魔女〉与〈白衣骑士〉","aliases":[],"summary":"珠雫与有栖院道别后前往广岛，拜访药师雾子并请求学习医疗技术。她接受严苛的身体训练与痛苦风险，雾子在约定必要时中断意识后开始施术。"},{"key":"第三章","title":"法米利昂皇国","aliases":[],"summary":"一辉随史黛菈前往法米利昂，接触皇室与热情的国民，也面对席琉斯围绕女儿婚事设下的考验。他突破国民的阻拦来到史黛菈身边，赢得接纳，并承诺不辜负全国寄予的期待。"},{"key":"第四章","title":"惨剧开幕","aliases":[],"summary":"奎多兰代表准备与法米利昂交战，却在训练设施中遭遇同伴失控杀人的惨剧。约翰的行为并非出自本人意志，傀儡王的威胁浮现，联盟派熟知其恐怖的阿斯卡里德前往法米利昂。"}]},{"volume":11,"title":"第11卷","chapters":[{"key":"第五章","title":"〈落第骑士（Worst One）〉VS〈红莲狂狮〉！？","aliases":[],"summary":"席琉斯因女儿的冷淡烦恼，仍以各种测试与一辉较劲，一辉选择认真接受岳父的考验。露娜艾丝接到奎多兰来电后，请一辉次日上午与她一同出访邻国。"},{"key":"第六章","title":"杀戮之夜","aliases":[],"summary":"风祭一行抵达阿尔卑斯，发现解放军总部与周围山峰遭到毁灭性袭击。欧尔·格尔与华伦斯坦交战，沙漠死神出手救下前者；亚伯拉汉·卡特随后闯入，世界势力的均衡开始动摇。"},{"key":"第七章","title":"访问奎多兰","aliases":[],"summary":"约翰以商讨傀儡王威胁及会见七星剑武祭优胜者为由，邀请露娜艾丝与一辉访问奎多兰。史黛菈在两国人民的生活中重申保护故乡与邻国的心愿，却被突如其来的否定声打断。"},{"key":"第八章","title":"名为「法米利昂」的国家","aliases":[],"summary":"欧尔·格尔现身并发动杀人戏曲，将史黛菈对和平的期望变为迫在眉睫的灾难。阿斯卡里德说明弟弟以他人痛苦取乐的本性，以及操纵军队的中继站机制，一辉因此向席琉斯提出应对方案。"},{"key":"第九章","title":"卡尔迪亚城镇战","aliases":[],"summary":"法米利昂军在卡尔迪亚布防，尝试以非致命方式解救遭操控的奎多兰士兵。史黛菈遇上沙漠死神的压倒性威胁，宁音加入战斗；露娜艾丝最终宣布接受五人代表战，并拒绝联盟直接介入两国领地。"}]},{"volume":12,"title":"第12卷","chapters":[{"key":"间章","title":"第一皇女的决心","aliases":[],"summary":"露娜艾丝在医院得知父王决定出兵救助遭操纵的友邦，担忧此举扩大本国人民的牺牲。她以减少损失的政治职责压过与约翰的私人情谊，下令立即前往奎多兰。"},{"key":"第十章","title":"皇族的职责","aliases":[],"summary":"奎多兰士兵突然停止行动，露娜艾丝的交涉把全面冲突转为皇室必须承担的代表战。史黛菈意识到自己与魔人的差距，决定前往爱沙尼亚挑战爱德怀斯，席琉斯则为女儿的冒险深感不安。"},{"key":"第十一章","title":"洁白之巅","aliases":[],"summary":"众人前往爱德怀斯隐居的爱德贝格，面对世界顶尖剑士的威压与史黛菈急于赴死的心态。爱德怀斯接受挑战，以独自阻挡登山挑战者换取最后一天应战为条件，史黛菈与同行者立下不由他人代战的约定。"},{"key":"第十二章","title":"严寒的考验","aliases":[],"summary":"史黛菈在严寒高山上独力阻挡冲着爱德怀斯赏金而来的挑战者。多多良指出她在热量与战斗运用上的浪费，帮助她调整消耗；修行末段，一股足以匹敌顶尖强者的陌生霸气逼近。"},{"key":"第十三章","title":"来自〈神龙寺〉的刺客","aliases":[],"summary":"神龙寺的福小莉到来，史黛菈被迫在显著的实力差距中迎战。她重新确认自己要与珍爱的人共同活下去，而非为职责赴死，并以不熄的信念突破绝境；六天修行就此告一段落。"},{"key":"第十四章","title":"法米利昂之剑","aliases":[],"summary":"福小莉一战结束后，史黛菈等人返回法米利昂的战场。国民拒绝独自避难，坚持与皇室同甘共苦，露娜艾丝也从妹妹的成长中看见新的希望，决定留下来相信她。"}]},{"volume":13,"title":"第13卷","chapters":[{"key":"间章1","title":"凶信","aliases":["间章"],"summary":"法米利昂为卡尔迪亚战役的死者举行传统国葬，留下的国民以晚宴与火光悼念亡者。席琉斯与一辉谈论史黛菈的成长，阿斯特蕾亚随后带来联盟总部的紧急消息。"},{"key":"第十五章","title":"月下乱斗","aliases":[],"summary":"代表战前夜，联盟大军在奎多兰国境布下封锁与干预兵力，却遭遇魔人的挑战。海王与沙漠死神展开激战；法米利昂代表们各自度过最后一夜，怀着共同求胜的决心迎接决战。"},{"key":"第十六章","title":"王都开战","aliases":[],"summary":"两国以奎多兰王都为战场展开五对五代表战，一辉与史黛菈分别迎击敌方选手。法米利昂在开战十分钟内取得两场胜利，史黛菈击败约翰后立即转向支援同伴，其他战场仍在激战。"},{"key":"第十七章","title":"不转杀手","aliases":[],"summary":"多多良在王城玫瑰园与艾茵交手，暗狱之家的过去和她对旧有归属的执着随战斗浮现。惨烈死斗把她逼近死亡，她却想起史黛菈的约定，努力维持意识，并把保护史黛菈的希望寄托给一辉。"},{"key":"第十八章","title":"狂飙突进","aliases":[],"summary":"艾莉丝失去亲人后被阿斯卡里德收养的经历，与她如今追击欧尔·格尔的行动交错展开。她抵抗弟弟试图再次操控自己的丝线，史黛菈随后赶到，以火焰巨剑向元凶发动攻击。"},{"key":"间章2","title":"迟来的魔女","aliases":[],"summary":"联盟医疗支援队抵达法米利昂，准备通过预先设置的大门救治代表战伤者。被误认为白衣骑士的少女其实是珠雫：雾子留在日本支援越狱事件，她以亲传弟子的身份代师前来。"}]},{"volume":14,"title":"第14卷","chapters":[{"key":"间章","title":"泪雨","aliases":[],"summary":"多年以前的雨夜，黑乃向宁音说明自己为何停在觉醒的门槛前：她珍惜与琢海相守的生活，不愿失去作为人的情感。宁音难以接受宿敌选择不同道路，黑乃随后宣布从KOK引退。"},{"key":"第十九章","title":"魔人对决","aliases":[],"summary":"五对五战局已倾向法米利昂，但沙漠死神与傀儡王仍未倒下。宁音迎战展露非人姿态的纳西姆，被逼面对自身对极限战斗的渴望，以及是否舍弃人类部分、彻底释放力量的选择。"},{"key":"第二十章","title":"难舍的情谊","aliases":[],"summary":"宁音回想暴力的成长经历与黑乃带来的转变，重新面对难以割舍的人际联系。她在激战中创造翻天覆地，将纳西姆放逐到四维空间之外；耗尽力量后，她把剩余战局交托给史黛菈。"},{"key":"第二十一章","title":"天理难容的心愿","aliases":[],"summary":"史黛菈赶来追击欧尔·格尔，局势却因艾莉丝保护弟弟的选择骤变。她与一辉各自坚持无法兼容的骑士道，最终以黑骑士与七星剑王的身份正面决斗。"}]},{"volume":15,"title":"第15卷","chapters":[{"key":"间章","title":"遗言","aliases":[],"summary":"一辉的胸膛遭到重创，灵装脱手，生命与意识迅速流失。面对无法挽回的死亡，他向史黛菈留下爱意的告白，回顾相遇以来的时日而无悔。"},{"key":"第二十二章","title":"剑神","aliases":[],"summary":"一辉与选择护弟的艾莉丝展开决斗，欧尔·格尔仍把姐姐的牺牲当作取乐的素材。一辉赢下这场残酷交锋后，通过主动分解自身组织争取恢复行动力，为接下来的战斗作准备。"},{"key":"第二十三章","title":"法米利昂的怒火","aliases":[],"summary":"黑骑士死亡的消息传遍战场，史黛菈继续压制欧尔·格尔，终于使他的恶行迎来报应。然而敌人准备了只有死亡后才能发动的死灵游戏，把自身遗骸化为散播破坏的最后手段。"},{"key":"第二十四章","title":"遗骸洒泪","aliases":[],"summary":"欧尔·格尔的遗体在死灵游戏作用下重组，战斗远未因肉身死亡而结束，一辉也在抵抗中遭到致命创伤。史黛菈最终将仇敌化为灰烬，留下少许骨灰与其姐姐合葬，并宣告两国战争结束。"},{"key":"第二十五章","title":"胜负已分，在那之后……","aliases":[],"summary":"一辉从死亡般的黑暗中醒来，得知珠雫以自身细胞暂时嫁接、重构他的身体。获救后的他面对史黛菈的痛苦与怒意，两人重新确认彼此；战后的幸存者也开始寻找继续生活的可能。"},{"key":"终章","title":"正义从天而降","aliases":[],"summary":"法米利昂与奎多兰开始修复战争创伤，但解放军总部的毁灭已改变国际局势。美军PSYON降临阿尔卑斯，亚伯拉罕当面逼问月影与风祭晄三，要求他们在美国定义的敌我之间表态。"}]},{"volume":16,"title":"第16卷","chapters":[{"key":"终章Ⅱ","title":"思乡","aliases":[],"summary":"傀儡王引发的战争结束，众人处理战后身体变化与归乡安排。珠雫检查确认史黛菈目前仍保持人类状态；史黛菈思念日本的朋友，却不知道大炎已经脱逃，新的灾难正在故乡酝酿。"},{"key":"序章","title":"深渊熅火","aliases":[],"summary":"沉睡于黑暗中的存在把人类的生命看作点灭的星光，珍惜又怜悯其短暂与无力。他预感深沉的永夜将再次降临，并把自己的苏醒理解为培育新时代巨星的使命。"},{"key":"第一章","title":"众劲敌的此刻","aliases":[],"summary":"欧尔·格尔收回操纵世界各地人员的丝线，引发大规模越狱，日本学生骑士接受特别征召参与镇压。刀华率领破军同伴搜捕罪犯并扫荡地下势力，一周内协助日本分部重新逮捕九成越狱犯。"},{"key":"第二章","title":"〈剑士杀手〉VS〈浪速之星〉","aliases":[],"summary":"特别征召结束，藏人与诸星在聚集的学生面前交手，藏人最终获判胜利，却察觉对手在决胜瞬间散发异常气势。另一边，黑铁严确认严密监禁的播磨天童已经脱逃，立即要求通报总部。"},{"key":"第三章","title":"〈大炎〉","aliases":[],"summary":"刀华、泡沫与彼方返乡探访若叶之家，育幼院的日常与邻里矛盾重新牵动刀华对家人的感情。她与受收留的老人来到父母墓前，冲突中揭开对方身份：老人正是天导众教主大炎，随后显现天丛云剑迎战。"}]},{"volume":17,"title":"第17卷","chapters":[{"key":"间章","title":"波纹逐渐扩散","aliases":[],"summary":"彼方在慈善基金会处理若叶之家的问题，接到黑铁严关于育幼院所收留老人的紧急联系。严判断普通骑士无法应付播磨天童，在黑乃赶往福冈的同时，向武曲学园请求征召能够迎战的学生。"},{"key":"第四章","title":"恩宠的力量","aliases":[],"summary":"刀华与显现天丛云剑的大炎交锋，亲身面对其异常力量。她试图再战时被命运锁链的幻景与剧痛阻挡；应对九州危机的会议尚未解决困局，黑乃便收到美军舰队逼近日本的警报。"},{"key":"第五章","title":"命运锁链","aliases":[],"summary":"美国太平洋舰队逼近，日本被迫同时面对外来军事威胁与九州的大炎。避难中的恐惧引发争执，若叶之家的长辈仍以保护孩子回应；刀华则一再承受死亡般的幻觉，试图挣脱命运锁链。"},{"key":"第六章","title":"两场大战·首都保卫战","aliases":[],"summary":"东京进入紧急防御，市民避难，军队与魔法骑士共同抵挡美军攻势，折木以共享幻痛的能力压制敌军。九州方面，刀华接受诸星提出的协同行动，众人开始联手准备讨伐大炎。"},{"key":"第七章","title":"两场大战·〈大炎〉讨伐战","aliases":[],"summary":"天童回顾自己把超度觉醒当成恩宠的过去，诸星、藏人与众人协力为刀华创造攻击机会。刀华汇聚同伴托付的力量迎战，最终消灭大炎；天童在消散中承认自身软弱与罪行，重新找回人的悔意。"},{"key":"尾声","title":"急转直下","aliases":[],"summary":"刀华击败天童后力竭落地，九州危机解除，日本准备把尚能作战的骑士调回东京。作战中心随后收到月影已获保护、并与黑铁严之子一起抵达对马的消息，推翻了敌方所宣称的拘押局面。"}]},{"volume":18,"title":"第18卷","chapters":[{"key":"序章","title":"所谓正义，所谓邪恶","aliases":[],"summary":"解放军总部毁灭后，美军以正义与秩序为名逼迫月影和风祭晄三，并利用对暴君真相的片面叙述划分敌我。王马听到夏洛特求援后，循风追踪被带走的众人。"},{"key":"第一章","title":"〈烈风剑帝〉VS〈超人(Thehero)〉","aliases":[],"summary":"月影等人被带进捷克斯洛伐克的美军基地，亚伯拉罕在此实施拘禁与精神干涉。王马赶来迎战，看到同伴受到折磨后放下平日求道的限制，动用外界风力强化斩击；众人随后筹划尽快返回日本。"},{"key":"第二章","title":"屠尽三千世界之鸦","aliases":[],"summary":"东京陷入火海，黑乃、折木与各地骑士苦战抵御美军及其兵器，首都防线一度濒临崩溃。法米利昂与九州两条战线的援军陆续赶回，扭转地上与地下战况，黑铁严最终宣布日本赢得这场战争。"},{"key":"第三章","title":"圣母史黛菈","aliases":[],"summary":"首都防卫战结束，月影与晄三面对接踵而来的隐患，一辉和史黛菈则短暂回到彼此相处的日常。爱兰兹突然袭击，重伤一辉并带走史黛菈，把她的命运与新的最终战役连接起来。"}]},{"volume":19,"title":"第19卷","chapters":[{"key":"间章","title":"遭囚的皇女","aliases":[],"summary":"史黛菈被囚于日光废矿深处的秘密实验室，爱兰兹计划以她为母体推进暴君灵魂转生的实验。亚伯拉罕通过药剂、供氧控制与精神操控削弱她的人格，手术只剩数小时便会完成。"},{"key":"第四章","title":"划破黑暗","aliases":[],"summary":"一辉从重伤中苏醒，伙伴们联合突入爱兰兹藏身的废矿设施，刀华与王马为救援队突破敌阵。抵达实验室后，他得知史黛菈的人格即将被抹除，必须在有限时间内突破达尔文的阻挡。"},{"key":"第五章","title":"〈大教授〉","aliases":[],"summary":"黑铁严向联盟通报救援危机，一辉则在实验室中与爱兰兹展开生死攻防，以临场变化挑战对方的能力优势。史黛菈表面获救，却已经被敌人借用身体刺伤一辉，并在密闭空间释放毁灭性火焰。"},{"key":"第六章","title":"最爱，也是最强的劲敌","aliases":[],"summary":"地下实验室被火焰摧毁后，一辉与伙伴继续抢救史黛菈，爱德怀斯也投入战斗。一辉进入她受虚假记忆囚禁的心灵，唤回最爱且最强的劲敌；危机结束后，严与月影决意由上一代收拾遗留的世界秩序问题。"},{"key":"终章","title":"背负憧憬的意义","aliases":[],"summary":"一连串战役过去，时间来到十月，一辉在延长的暑假中继续训练，准备挑战更高层级的舞台。他逐渐承认自己努力赢来的价值，与史黛菈珍惜共同度过的时光，并肩走向新的未来。"}]}];
function getStoryVolume(volume) {
  return Number.isInteger(volume) ? STORY_VOLUMES.find(item => item.volume === volume) || null : null;
}
function resolveStoryChapter(volume, key) {
  if (typeof key !== 'string' || !key.trim()) return null;
  const chapters = getStoryVolume(volume)?.chapters || [];
  const value = key.trim();
  return chapters.find(chapter => chapter.key === value) ||
    chapters.find(chapter => (chapter.aliases || []).includes(value)) || null;
}
function firstStoryChapter(volume) {
  return getStoryVolume(volume)?.chapters[0] || null;
}
function storyPosition(volume, key) {
  const chapter = resolveStoryChapter(volume, key);
  if (!chapter) return -1;
  let offset = 0;
  for (const book of STORY_VOLUMES) {
    if (book.volume === volume) return offset + book.chapters.indexOf(chapter);
    offset += book.chapters.length;
  }
  return -1;
}
function nextStoryChapter(volume, key) {
  const current = resolveStoryChapter(volume, key), book = getStoryVolume(volume);
  if (!current || !book) return null;
  const next = book.chapters[book.chapters.indexOf(current) + 1];
  if (next) return { volume, chapter: next.key };
  const following = STORY_VOLUMES[STORY_VOLUMES.indexOf(book) + 1];
  return following ? { volume: following.volume, chapter: following.chapters[0].key } : null;
}

