        continue;
      }
      if (field === '支援度' && old && (typeof prior !== 'number' || !Number.isFinite(prior))) {
        reject(field, '旧记录支援度待核定，请由玩家在变量编辑器确认起始值；模型不能自行按旧字母倒填或从 0 重置。');
